from typing import List


class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        if k == 1:
            best = cur = 0
            for v in nums:
                cur = max(0, cur + v)
                best = max(best, cur)
            return best
        best_min = [float('inf')] * k
        best_min[0] = 0
        prefix = 0
        answer = float('-inf')
        for i, v in enumerate(nums, 1):
            prefix += v
            r = i % k
            if best_min[r] != float('inf'):
                answer = max(answer, prefix - best_min[r])
            best_min[r] = min(best_min[r], prefix)
        return answer

from typing import List


class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        if k == 1:
            return sum(v for v in nums if v > 0) or max(nums)
        best_min = [float('inf')] * k
        best_min[0] = 0
        prefix = 0
        answer = float('-inf')
        for i, v in enumerate(nums, 1):
            prefix += v
            r = i % k
            if best_min[r] != float('inf'):
                answer = max(answer, prefix - best_min[r])
            best_min[r] = min(best_min[r], prefix)
        return answer
